base.css:
* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #151515;
  color: #f0f0f0;
  font-family: DM Sans, system-ui, sans-serif;
}

button, a {
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
}

a {
  color: inherit;
}

a:focus-visible, button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 4px;
}

.library-layout {
  position: relative;
  display: grid;
  grid-template-columns: 23.3333% 20% 56.6667%;
  grid-template-rows: minmax(0, 1fr);
  height: 100vh;
  height: 100svh;
  min-height: 0;
  overflow: hidden;
  isolation: isolate;
}

.chat-background {
  position: relative;
  grid-column: 1;
  grid-row: 1;
  min-height: 0;
  overflow: hidden;
  background: #181818;
  z-index: 0;
  border-right: 1px solid #363636;
}

.chat-background:after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(#0000 20%, #18181840 45%, #181818 86%);
}

.chat-stream {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: 30px 22px;
  animation: 48s linear infinite chat-scroll;
  opacity: .42;
  filter: blur(.2px);
}

.chat-cycle {
  display: grid;
  gap: 19px;
  padding-bottom: 19px;
}

.bubble {
  font-size: 14px;
  line-height: 1.65;
  max-width: 94%;
  margin: 0;
  padding: 14px 17px;
  background: #2b2b2b;
  border: 1px solid #444;
  border-radius: 12px 12px 12px 2px;
  color: #d6d6d6;
}

.bubble:nth-child(2n) {
  margin-left: 30px;
  background: #333;
  border-radius: 12px 12px 2px;
  color: #ddd;
}

.chat-background:hover .chat-stream, .chat-background:focus-within .chat-stream, .chat-background.paused .chat-stream {
  animation-play-state: paused;
}

.chat-pause {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  border: 1px solid #555;
  border-radius: 4px;
  background: #222;
  color: #ccc;
  font-size: 11px;
  padding: 7px 10px;
  cursor: pointer;
}

.portrait-region {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 23.3333%;
  height: min(440px, 70%);
  padding: 22px 20px 25px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: linear-gradient(#0000, #181818 20%);
}

.portrait-stage {
  position: relative;
  width: calc(100% + 16px);
  margin-left: -8px;
  height: 280px;
  min-height: 0;
  flex-shrink: 1;
  overflow: hidden;
  border-radius: 0;
  background: none;
  border: 0;
}

.portrait-stage img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center bottom;
  visibility: hidden;
  background: none;
}

.portrait-stage img.active {
  visibility: visible;
}

.portrait-region h1 {
  font-family: Bricolage Grotesque, system-ui, sans-serif;
  font-size: 31px;
  line-height: 1.07;
  letter-spacing: -1.1px;
  font-weight: 650;
  margin: 22px 0 0;
  max-width: 285px;
  flex-shrink: 0;
}

.project-shelf {
  grid-column: 2;
  grid-row: 1;
  z-index: 5;
  position: relative;
  min-height: 0;
  padding: 42px 23px 110px;
  background: #252525;
  border-right: 1px solid #484848;
  box-shadow: inset 8px 0 22px #00000015;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.project-shelf h2 {
  font-family: Bricolage Grotesque, system-ui, sans-serif;
  font-size: 34px;
  font-weight: 600;
  letter-spacing: -1.3px;
  line-height: 1.1;
  margin: 0 0 39px;
  flex-shrink: 0;
}

.books {
  display: flex;
  flex-direction: column;
  gap: 15px;
  overflow-y: auto;
  min-height: 0;
  padding: 6px 5px 14px;
  margin: -6px -5px 0;
  scrollbar-width: thin;
  scrollbar-color: #777 #252525;
}

.book {
  --spine: #45574c;
  position: relative;
  display: flex;
  align-items: center;
  min-height: 66px;
  flex-shrink: 0;
  padding: 15px 17px 15px 24px;
  border-radius: 4px 8px 8px 4px;
  border: 1px solid #ffffff21;
  background: var(--spine);
  color: #f6f0df;
  text-decoration: none;
  box-shadow: 0 5px #111, 0 8px 10px #0003, inset 5px 0 #ffffff0b, inset 8px 0 #0002;
  transition: transform .18s, filter .18s;
  font-family: Bricolage Grotesque, system-ui, sans-serif;
  font-size: 18px;
  line-height: 1.17;
  font-weight: 600;
  letter-spacing: -.35px;
}

.book:before {
  content: "";
  position: absolute;
  left: 12px;
  top: 7px;
  bottom: 7px;
  border-left: 1px solid #ffffff2b;
}

.book:after {
  content: "↗";
  margin-left: auto;
  padding-left: 8px;
  font-family: system-ui, sans-serif;
  font-size: 17px;
  opacity: .65;
}

.book:hover, .book:focus-visible {
  transform: translateY(-6px);
  filter: brightness(1.12);
}

.book[aria-current="true"] {
  outline: 1px solid #ddd;
  outline-offset: 4px;
}

.book:nth-child(2) {
  --spine: #665844;
  margin-left: 8px;
}

.book:nth-child(3) {
  --spine: #4d5366;
  margin-right: 6px;
}

.book:nth-child(4) {
  --spine: #704e43;
  margin-left: 5px;
}

.book:nth-child(5) {
  --spine: #586444;
  margin-right: 4px;
}

.book:nth-child(6) {
  --spine: #5b4756;
  margin-left: 7px;
  min-height: 80px;
}

.book:nth-child(7) {
  --spine: #3e5a59;
}

.project-frame {
  grid-column: 3;
  grid-row: 1;
  min-width: 0;
  min-height: 0;
  position: relative;
  z-index: 6;
  display: flex;
  flex-direction: column;
  background: #111;
  overflow: hidden;
}

.frame-bar {
  height: 64px;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 25px;
  border-bottom: 1px solid #383838;
  background: #1d1d1d;
  font-size: 14px;
}

.frame-bar span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.frame-bar a {
  text-decoration: none;
  color: #ddd;
  font-size: 13px;
  white-space: nowrap;
}

.frame-bar a:hover {
  text-decoration: underline;
}

.project-frame iframe {
  display: block;
  width: 100%;
  height: 0;
  flex: 1;
  min-height: 0;
  border: 0;
  background: #181818;
  color-scheme: dark;
}

.contact-region {
  position: absolute;
  left: calc(23.3333% + 8px);
  bottom: 4px;
  width: calc(20% - 16px);
  height: 88px;
  z-index: 7;
  padding: 8px;
  display: flex;
  align-items: stretch;
  background: #252525ef;
  border-radius: 8px;
  box-shadow: 0 -8px 25px #252525;
}

.contact-region a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  padding: 0 20px;
  border: 1px solid #ddd;
  border-radius: 4px;
  background: #e0e0e0;
  color: #202020;
  font-size: 17px;
  font-weight: 650;
  text-decoration: none;
  box-shadow: 0 3px #111;
  transition: transform .16s;
}

.contact-region a:hover {
  transform: translateY(-2px);
}

.contact-region span {
  font-size: 25px;
  font-weight: 400;
}

@keyframes chat-scroll {
  to {
    transform: translateY(-50%);
  }
}

@media (width >= 1800px) {
  .portrait-stage {
    height: 300px;
  }
}

@media (width <= 1000px) and (width >= 761px) {
  .project-shelf {
    padding-left: 14px;
    padding-right: 14px;
  }

  .book {
    font-size: 15px;
    padding-left: 20px;
  }

  .project-shelf h2 {
    font-size: 29px;
  }

  .portrait-region {
    padding-left: 12px;
    padding-right: 12px;
  }

  .portrait-region h1 {
    font-size: 27px;
  }

  .portrait-stage {
    height: 250px;
  }

  .contact-region a {
    font-size: 14px;
    padding: 0 10px;
  }
}

@media (width <= 760px) {
  .library-layout {
    grid-template-columns: 44% 56%;
    grid-template-rows: minmax(0, 45fr) minmax(0, 55fr);
  }

  .chat-background {
    grid-column: 1;
    grid-row: 1;
    min-height: 0;
  }

  .portrait-region {
    top: 44px;
    bottom: auto;
    width: 44%;
    height: calc(45% - 44px);
    align-items: center;
    padding: 10px 14px 16px;
  }

  .portrait-stage {
    width: calc(100% + 16px);
    height: 100%;
    margin-left: 0;
  }

  .portrait-region h1 {
    font-size: clamp(18px, 4.5vw, 28px);
    width: 100%;
    margin-top: 10px;
  }

  .project-shelf {
    grid-column: 2;
    grid-row: 1;
    min-height: 0;
    padding: 18px 16px 66px;
  }

  .project-shelf h2 {
    font-size: 25px;
    margin-bottom: 18px;
  }

  .books {
    gap: 12px;
  }

  .book {
    min-height: 48px;
    font-size: 14px;
    padding: 12px 10px 12px 20px;
  }

  .book:nth-child(6) {
    min-height: 60px;
  }

  .project-frame {
    grid-column: 1 / -1;
    grid-row: 2;
    min-height: 0;
  }

  .frame-bar {
    height: 46px;
    padding: 0 16px;
  }

  .contact-region {
    left: calc(44% + 8px);
    bottom: calc(55% + 6px);
    width: calc(56% - 16px);
    height: 50px;
    padding: 4px;
    box-shadow: 0 -5px 14px #252525;
  }

  .contact-region a {
    font-size: 14px;
    padding: 0 12px;
  }

  .contact-region span {
    font-size: 20px;
  }

  .chat-stream {
    padding: 24px 12px;
  }

  .chat-pause {
    font-size: 10px;
    right: 8px;
    top: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-stream {
    animation: none;
  }

  .book, .contact-region a {
    transition: none;
  }

  .book:hover, .book:focus-visible, .contact-region a:hover {
    transform: none;
  }
}

